import{_ as e,o as a,c as n,a0 as t}from"./chunks/framework.DCluYYrN.js";const u=JSON.parse('{"title":"モジュールのガイド","description":"","frontmatter":{},"headers":[],"relativePath":"ja_JP/guide/module.md","filePath":"ja_JP/guide/module.md"}'),l={name:"ja_JP/guide/module.md"};function o(i,s,p,d,c,r){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="モジュールのガイド" tabindex="-1">モジュールのガイド <a class="header-anchor" href="#モジュールのガイド" aria-label="Permalink to &quot;モジュールのガイド&quot;">​</a></h1><p>KernelSU はシステムパーティションの整合性を維持しながら、システムディレクトリを変更する効果を実現するモジュール機構を提供します。この機構は一般に「システムレス」と呼ばれています。</p><p>KernelSU のモジュール機構は、Magisk とほぼ同じです。Magisk のモジュール開発に慣れている方であれば、KernelSU のモジュール開発も簡単でしょう。その場合は以下のモジュールの紹介は読み飛ばして、<a href="./difference-with-magisk.html">Magisk との違い</a>の内容だけ読めばOKです。</p><div class="warning custom-block"><p class="custom-block-title">METAMODULE はシステムファイル変更時のみ必要</p><p>KernelSU は <a href="./metamodule.html">metamodule</a> アーキテクチャを使用して <code>system</code> ディレクトリをマウントします。<strong>モジュールが <code>/system</code> ファイルを変更する必要がある場合のみ</strong>（<code>system</code> ディレクトリ経由で）、metamodule (<a href="https://github.com/tiann/KernelSU/releases" target="_blank" rel="noreferrer">meta-overlayfs</a>など) をインストールする必要があります。スクリプト、sepolicy ルール、system.propなどの他のモジュール機能は metamodule なしで動作します。</p></div><h2 id="webui" tabindex="-1">WebUI <a class="header-anchor" href="#webui" aria-label="Permalink to &quot;WebUI&quot;">​</a></h2><p>KernelSU modules support displaying interfaces and interacting with users. See the <a href="./module-webui.html">WebUI documentation</a> for more information.</p><h2 id="モジュール設定" tabindex="-1">モジュール設定 <a class="header-anchor" href="#モジュール設定" aria-label="Permalink to &quot;モジュール設定&quot;">​</a></h2><p>KernelSU は、モジュールが永続的または一時的なキー値設定を保存できる組み込みの設定システムを提供します。詳細については、<a href="./module-config.html">モジュール設定ドキュメント</a>を参照してください。</p><h2 id="ワンショットスクリプト" tabindex="-1">ワンショットスクリプト <a class="header-anchor" href="#ワンショットスクリプト" aria-label="Permalink to &quot;ワンショットスクリプト&quot;">​</a></h2><p>モジュール ZIP は、KernelSU マネージャーがインストールせずに一度だけ実行するワンショットスクリプトにすることもできます。詳細については、<a href="./module-script.html">ワンショットスクリプトのドキュメント</a>を参照してください。</p><h2 id="busybox" tabindex="-1">Busybox <a class="header-anchor" href="#busybox" aria-label="Permalink to &quot;Busybox&quot;">​</a></h2><p>KernelSU には、機能的に完全な Busybox バイナリ (SELinux の完全サポートを含む) が同梱されています。実行ファイルは <code>/data/adb/ksu/bin/busybox</code> に配置されています。KernelSU の Busybox はランタイムに切り替え可能な「ASH スタンドアローンシェルモード」をサポートしています。このスタンドアロンモードとは、Busybox の <code>ash</code> シェルで実行する場合 <code>PATH</code> として設定されているものに関係なく、すべてのコマンドが Busybox 内のアプレットを直接使用するというものです。たとえば、<code>ls</code>、<code>rm</code>、<code>chmod</code> などのコマンドは、<code>PATH</code> にあるもの（Android の場合、デフォルトではそれぞれ <code>/system/bin/ls</code>, <code>/system/bin/rm</code>, <code>/system/bin/chmod</code>）ではなく、直接 Busybox 内部のアプレットを呼び出すことになります。これにより、スクリプトは常に予測可能な環境で実行され、どの Android バージョンで実行されていても常にコマンドを利用できます。Busybox を使用しないコマンドを強制的に実行するには、フルパスで実行ファイルを呼び出す必要があります。</p><p>KernelSU のコンテキストで実行されるすべてのシェルスクリプトは、Busybox の <code>ash</code> シェルでスタンドアロンモードが有効な状態で実行されます。サードパーティの開発者に関係するものとしては、すべてのブートスクリプトとモジュールのインストールスクリプトが含まれます。</p><p>この「スタンドアロンモード」機能を KernelSU 以外で使用したい場合、2つの方法で有効にできます：</p><ol><li>環境変数 <code>ASH_STANDALONE</code> を <code>1</code> にする<br>例: <code>ASH_STANDALONE=1 /data/adb/ksu/bin/busybox sh &lt;script&gt;</code></li><li>コマンドラインのオプションで変更する:<br><code>/data/adb/ksu/bin/busybox sh -o standalone &lt;script&gt;</code></li></ol><p>環境変数が子プロセスに継承されるため、その後に実行されるすべての <code>sh</code> シェルもスタンドアロンモードで実行されるようにするにはオプション 1 が望ましい方法です（KernelSU と KernelSU Managerが内部的に使用しているのもこちらです）。</p><div class="tip custom-block"><p class="custom-block-title">Magisk との違い</p><p>KernelSU の Busybox は、Magisk プロジェクトから直接コンパイルされたバイナリファイルを使用するようになりました。Magisk と KernelSU の Busybox スクリプトはまったく同じものなので、互換性の問題を心配する必要はありません！</p></div><h2 id="kernelsu-モジュール" tabindex="-1">KernelSU モジュール <a class="header-anchor" href="#kernelsu-モジュール" aria-label="Permalink to &quot;KernelSU モジュール&quot;">​</a></h2><p>KernelSU モジュールは、<code>/data/adb/modules</code> に配置された以下の構造を持つフォルダーです：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── $MODID                  &lt;--- フォルダの名前はモジュールの ID で付けます</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** モジュールの ID ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── module.prop         &lt;--- このファイルにモジュールのメタデータを保存します</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** メインコンテンツ ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── system              &lt;--- skip_mount が存在しない場合、このフォルダがマウントされます</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** ステータスフラグ ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── skip_mount          &lt;--- 存在する場合、KernelSU はシステムフォルダをマウントしません</span></span>
<span class="line"><span>│   ├── disable             &lt;--- 存在する場合、モジュールは無効化されます</span></span>
<span class="line"><span>│   ├── remove              &lt;--- 存在する場合、次の再起動時にモジュールが削除されます</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 任意のファイル ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── post-fs-data.sh     &lt;--- このスクリプトは post-fs-data で実行されます</span></span>
<span class="line"><span>│   ├── service.sh          &lt;--- このスクリプトは late_start サービスで実行されます</span></span>
<span class="line"><span>|   ├── uninstall.sh        &lt;--- このスクリプトは KernelSU がモジュールを削除するときに実行されます</span></span>
<span class="line"><span>│   ├── system.prop         &lt;--- このファイルのプロパティは resetprop によってシステムプロパティとして読み込まれます</span></span>
<span class="line"><span>│   ├── sepolicy.rule       &lt;--- カスタム SEPolicy ルールを追加します</span></span>
<span class="line"><span>│   ├── initrc/             &lt;--- このディレクトリ内の .rc ファイルは起動時に init.rc に挿入されます</span></span>
<span class="line"><span>│   │   ├── myservice.rc</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 自動生成されるため、手動で作成または変更しないでください ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── vendor              &lt;--- $MODID/system/vendor へのシンボリックリンク</span></span>
<span class="line"><span>│   ├── product             &lt;--- $MODID/system/product へのシンボリックリンク</span></span>
<span class="line"><span>│   ├── system_ext          &lt;--- $MODID/system/system_ext へのシンボリックリンク</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** その他のファイル/フォルダの追加も可能です ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── ...</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── another_module</span></span>
<span class="line"><span>│   ├── .</span></span>
<span class="line"><span>│   └── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Magisk との違い</p><p>KernelSU は Zygisk をビルトインでサポートしていないため、モジュール内に Zygisk に関連するコンテンツは存在しません。 しかし、<a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> をインストールすれば Zygisk モジュールを使えます。その場合の Zygisk モジュールのコンテンツは Magisk と同じです。</p></div><h3 id="module-prop" tabindex="-1">module.prop <a class="header-anchor" href="#module-prop" aria-label="Permalink to &quot;module.prop&quot;">​</a></h3><p>module.prop はモジュールの設定ファイルです。KernelSU ではこのファイルを含まないモジュールは、モジュールとして認識されません。このファイルの形式は以下の通りです：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>id=&lt;string&gt;</span></span>
<span class="line"><span>name=&lt;string&gt;</span></span>
<span class="line"><span>version=&lt;string&gt;</span></span>
<span class="line"><span>versionCode=&lt;int&gt;</span></span>
<span class="line"><span>author=&lt;string&gt;</span></span>
<span class="line"><span>description=&lt;string&gt;</span></span>
<span class="line"><span>updateJson=&lt;url&gt; (optional)</span></span>
<span class="line"><span>actionIcon=&lt;path&gt; (optional)</span></span>
<span class="line"><span>webuiIcon=&lt;path&gt; (optional)</span></span></code></pre></div><ul><li><code>id</code> はこの正規表現に一致していなければいけません: <code>^[a-zA-Z][a-zA-Z0-9._-]+$</code><br> 例: ✓ <code>a_module</code>, ✓ <code>a.module</code>, ✓ <code>module-101</code>, ✗ <code>a module</code>, ✗ <code>1_module</code>, ✗ <code>-a-module</code><br> これはモジュールの<strong>ユニークな ID</strong> です。公開後は変更しないでください。</li><li><code>versionCode</code> は <strong>integer</strong> です。バージョンの比較に使います。</li><li>他のものには<strong>単一行</strong> の文字であれば何でも使えます。</li><li>改行文字は <code>UNIX (LF)</code> を使ってください。<code>Windows (CR+LF)</code> や <code>Macintosh (CR)</code> は使ってはいけません。</li><li><code>actionIcon</code> と <code>webuiIcon</code> は、マネージャーアプリ内に表示される<strong>モジュールアクションのショートカット</strong>および<strong>WebUI ショートカット</strong>の既定アイコンとして使用される、任意指定の画像パスです。これらのパスは、モジュール ディレクトリを基準として指定する必要があります。例えば、<code>actionIcon=icon/icon.png</code> は <code>&lt;MODDIR&gt;/icon/icon.png</code> を指します。</li></ul><div class="tip custom-block"><p class="custom-block-title">動的説明</p><p><code>description</code> フィールドは、モジュール設定システムを使用して実行時に動的にオーバーライドできます。詳細は<a href="./module-config.html#overriding-module-description">モジュール説明のオーバーライド</a>を参照してください。</p></div><h3 id="シェルスクリプト" tabindex="-1">シェルスクリプト <a class="header-anchor" href="#シェルスクリプト" aria-label="Permalink to &quot;シェルスクリプト&quot;">​</a></h3><p><code>post-fs-data.sh</code> と <code>service.sh</code> の違いについては、<a href="#boot-scripts">ブートスクリプト</a>のセクションを読んでください。ほとんどのモジュール開発者にとって、ブートスクリプトを実行するだけなら <code>service.sh</code> で十分なはずです。</p><p>モジュールのすべてのスクリプトでは、<code>MODDIR=\${0%/*}</code>を使えばモジュールのベースディレクトリのパスを取得できます。スクリプト内でモジュールのパスをハードコードしないでください。</p><div class="tip custom-block"><p class="custom-block-title">Magisk との違い</p><p>環境変数 <code>KSU</code> を使用すると、スクリプトが KernelSU と Magisk どちらで実行されているかを判断できます。KernelSU で実行されている場合、この値は <code>true</code> に設定されます。</p></div><h3 id="system-ディレクトリ" tabindex="-1"><code>system</code> ディレクトリ <a class="header-anchor" href="#system-ディレクトリ" aria-label="Permalink to &quot;\`system\` ディレクトリ&quot;">​</a></h3><p>このディレクトリの内容は、システムの起動後に OverlayFS を使用してシステムの /system パーティションの上にオーバーレイされます：</p><ol><li>システム内の対応するディレクトリにあるファイルと同名のファイルは、このディレクトリにあるファイルで上書きされます。</li><li>システム内の対応するディレクトリにあるフォルダと同じ名前のフォルダは、このディレクトリにあるフォルダと統合されます。</li></ol><p>元のシステムディレクトリにあるファイルやフォルダを削除したい場合は、<code>mknod filename c 0 0</code> を使ってモジュールディレクトリにそのファイル/フォルダと同じ名前のファイルを作成する必要があります。こうすることで、OverlayFS システムはこのファイルを削除したかのように自動的に「ホワイトアウト」します（/system パーティションは実際には変更されません）。</p><p>また、<code>customize.sh</code> 内で <code>REMOVE</code> という変数に削除操作を実行するディレクトリのリストを宣言すると、KernelSU は自動的にそのモジュールの対応するディレクトリで <code>mknod &lt;TARGET&gt; c 0 0</code> を実行します。例えば</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REMOVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/YouTube</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/Bloatware</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>上記の場合は、<code>mknod $MODPATH/system/app/YouTuBe c 0 0</code>と<code>mknod $MODPATH/system/app/Bloatware c 0 0</code>を実行し、<code>/system/app/YouTube</code>と<code>/system/app/Bloatware</code>はモジュール有効化後に削除されます。</p><p>システム内のディレクトリを置き換えたい場合は、モジュールディレクトリに同じパスのディレクトリを作成し、このディレクトリに <code>setfattr -n trusted.overlay.opaque -v y &lt;TARGET&gt;</code> という属性を設定する必要があります。こうすることで、OverlayFS システムは（/system パーティションを変更することなく）システム内の対応するディレクトリを自動的に置き換えることができます。</p><p><code>customize.sh</code> ファイル内に <code>REPLACE</code> という変数を宣言し、その中に置換するディレクトリのリストを入れておけば、KernelSU は自動的にモジュールディレクトリに対応した処理を行います。例えば：</p><p>REPLACE=&quot; /system/app/YouTube /system/app/Bloatware &quot;</p><p>このリストは、自動的に <code>$MODPATH/system/app/YouTube</code> と <code>$MODPATH/system/app/Bloatware</code> というディレクトリを作成し、 <code>setfattr -n trusted.overlay.opaque -v y $MODPATH/system/app/YouTube</code> と <code>setfattr -n trusted.overlay.opaque -v y $MODPATH/system/app/Bloatware</code> を実行します。モジュールが有効になると、<code>/system/app/YouTube</code> と <code>/system/app/Bloatware</code> は空のディレクトリに置き換えられます。</p><div class="tip custom-block"><p class="custom-block-title">Magisk との違い</p><p>KernelSU のシステムレスメカニズムはカーネルの OverlayFS によって実装され、Magisk は現在マジックマウント（bind mount）を使用しています。この2つの実装方法には大きな違いがありますが最終的な目的は同じで、/system パーティションを物理的に変更することなく、/system のファイルを変更できます。</p></div><p>OverlayFS に興味があれば、Linux カーネルの <a href="https://docs.kernel.org/filesystems/overlayfs.html" target="_blank" rel="noreferrer">OverlayFS のドキュメンテーション</a> を読んでみてください。</p><h3 id="system-prop" tabindex="-1">system.prop <a class="header-anchor" href="#system-prop" aria-label="Permalink to &quot;system.prop&quot;">​</a></h3><p>このファイルは <code>build.prop</code> と同じ形式をとっています。各行は <code>[key]=[value]</code> で構成されます。</p><h3 id="sepolicy-rule" tabindex="-1">sepolicy.rule <a class="header-anchor" href="#sepolicy-rule" aria-label="Permalink to &quot;sepolicy.rule&quot;">​</a></h3><p>もしあなたのモジュールが追加の SEPolicy パッチを必要とする場合は、それらのルールをこのファイルに追加してください。このファイルの各行は、ポリシーステートメントとして扱われます。</p><h3 id="initrc-injection" tabindex="-1">initrc の挿入 <a class="header-anchor" href="#initrc-injection" aria-label="Permalink to &quot;initrc の挿入 {#initrc-injection}&quot;">​</a></h3><p>KernelSUは、カスタムの Android Init RC ディレクティブをシステムの <code>init.rc</code> に挿入するメカニズムを提供します。これにより、モジュールはシステムパーティションを変更することなく、カスタムAndroidサービスの登録、プロパティトリガーの設定、またはその他のInit言語アクションの実行を行うことができます。</p><p>起動中に、KernelSUカーネルモジュールは <code>read()</code> および <code>fstat()</code> システムコールをインターセプトします。Android initプロセスが <code>/system/etc/init/hw/init.rc</code> を読み取るときに、KernelSUはカスタムRCコンテンツをファイルの末尾に透過的に追加します。initプロセスは、元の init.rc コンテンツと同じように、これらの挿入されたディレクティブを解析します。</p><p>ユーザースペース側では、ksudが有効になっているモジュールからのすべての <code>.rc</code> ファイルを連結して1つの <code>modules.rc</code> ファイルを作成し、<code>/metadata</code> パーティションに保存します。このファイルは、モジュールの状態（インストール、有効化、無効化、アンインストールなど）が変更されるたびに自動的に再生成されます。</p><h4 id="モジュール-initrc-ファイル" tabindex="-1">モジュール initrc ファイル <a class="header-anchor" href="#モジュール-initrc-ファイル" aria-label="Permalink to &quot;モジュール initrc ファイル&quot;">​</a></h4><p>モジュールディレクトリに <code>initrc/</code> サブディレクトリを作成し、そこに <code>.rc</code> ファイルを配置します。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules/&lt;MODID&gt;/</span></span>
<span class="line"><span>├── initrc/</span></span>
<span class="line"><span>│   ├── myservice.rc</span></span>
<span class="line"><span>│   └── another.rc</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>ファイルの拡張子は <code>.rc</code> である必要があります。</li><li>モジュールが有効になっている限り、<code>initrc/</code> ディレクトリ内のすべての <code>.rc</code> ファイルが含まれます（実行権限は必要ありません）。</li><li>ファイルはディレクトリ内で<strong>ファイル名のアルファベット順</strong>に処理され、モジュールは<strong>モジュールIDのアルファベット順</strong>に処理されます。</li></ul></div><h4 id="一般的な-initrc-ファイル" tabindex="-1">一般的な initrc ファイル <a class="header-anchor" href="#一般的な-initrc-ファイル" aria-label="Permalink to &quot;一般的な initrc ファイル&quot;">​</a></h4><p>モジュールレベルのRCファイルに加えて、グローバルディレクトリに <code>.rc</code> ファイルを配置することもできます。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/initrc.d/</span></span>
<span class="line"><span>├── myservice.rc</span></span>
<span class="line"><span>└── another.rc</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">一般的な initrc ファイルには実行権限が必要です</p><p>モジュールの <code>initrc/</code> ディレクトリとは異なり、<code>/data/adb/initrc.d/</code> 内のファイルを含めるには<strong>実行権限が必要</strong>です。実行不可能な <code>.rc</code> ファイルは静かにスキップされます。</p></div><p>一般的な <code>initrc.d/</code> ファイルは、モジュールのRCファイルよりも前に処理されます。</p><h4 id="例" tabindex="-1">例 <a class="header-anchor" href="#例" aria-label="Permalink to &quot;例&quot;">​</a></h4><p>カスタムAndroidサービスを登録する <code>.rc</code> ファイルの例を次に示します。</p><div class="language-rc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>service myservice /data/adb/modules/mymodule/bin/myservice</span></span>
<span class="line"><span>    user root</span></span>
<span class="line"><span>    group root</span></span>
<span class="line"><span>    disabled</span></span>
<span class="line"><span>    seclabel u:r:ksu:s0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>on property:sys.boot_completed=1</span></span>
<span class="line"><span>    start myservice</span></span></code></pre></div><p>このファイルが <code>/data/adb/modules/mymodule/initrc/myservice.rc</code> に配置されている場合、起動時に <code>myservice</code> という名前のサービスを登録し、<code>sys.boot_completed=1</code> に達したときにサービスを開始します。</p><h4 id="手動更新" tabindex="-1">手動更新 <a class="header-anchor" href="#手動更新" aria-label="Permalink to &quot;手動更新&quot;">​</a></h4><p>次のコマンドを使用して、<code>modules.rc</code> の再生成を手動でトリガーできます（変更は次回の起動時に有効になります）。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> initrc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refresh</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>initrc の挿入は、起動プロセスの非常に早い段階（init が init.rc を読み取るとき）で、post-fs-data およびモジュールスクリプトが実行される<strong>前</strong>に行われます。</li><li>挿入されたRCコンテンツは、元の init.rc の一部として init によって扱われ、すべての Android Init 言語構文（サービス定義、トリガー、プロパティ設定など）をサポートします。</li><li>initrc の挿入は、システムコールフックがインストールされないため、<strong>late-load モード</strong>では<strong>使用できません</strong>。</li><li>ksudでイメージにパッチを当てる際に <code>--no-custom-rc</code> パラメータを渡すことで、モジュールRCの挿入を無効にすることができます。</li></ul></div><h2 id="モジュールのインストーラー" tabindex="-1">モジュールのインストーラー <a class="header-anchor" href="#モジュールのインストーラー" aria-label="Permalink to &quot;モジュールのインストーラー&quot;">​</a></h2><p>KernelSU モジュールインストーラーは、KernelSU Manager アプリでインストールできる、ZIP ファイルにパッケージされた KernelSU モジュールです。最もシンプルな KernelSU モジュールインストーラーは、KernelSU モジュールを ZIP ファイルとしてパックしただけのものです。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>module.zip</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── customize.sh                       &lt;--- (任意、詳細は後述)</span></span>
<span class="line"><span>│                                           このスクリプトは update-binary から読み込まれます</span></span>
<span class="line"><span>├── ...</span></span>
<span class="line"><span>├── ...  /* 残りのモジュールのファイル */</span></span>
<span class="line"><span>│</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">警告</p><p>KernelSU モジュールは、カスタムリカバリーからのインストールには非対応です！</p></div><h3 id="カスタマイズ" tabindex="-1">カスタマイズ <a class="header-anchor" href="#カスタマイズ" aria-label="Permalink to &quot;カスタマイズ&quot;">​</a></h3><p>モジュールのインストールプロセスをカスタマイズする必要がある場合、<code>customize.sh</code> という名前のスクリプトを作成してください。このスクリプトは、すべてのファイルが抽出され、デフォルトのパーミッションと secontext が適用された後、モジュールインストーラースクリプトによって読み込み (実行ではなく) されます。これは、モジュールがデバイスの ABI に基づいて追加設定を必要とする場合や、モジュールファイルの一部に特別なパーミッション/コンテキストを設定する必要がある場合に、非常に便利です。</p><p>インストールプロセスを完全に制御しカスタマイズしたい場合は、<code>customize.sh</code> で <code>SKIPUNZIP=1</code> と宣言すればデフォルトのインストールステップをすべてスキップできます。そうすることで、<code>customize.sh</code> が責任をもってすべてをインストールするようになります。</p><p><code>customize.sh</code>スクリプトは、KernelSU の Busybox <code>ash</code> シェルで、「スタンドアロンモード」を有効にして実行します。以下の変数と関数が利用可能です：</p><h4 id="変数" tabindex="-1">変数 <a class="header-anchor" href="#変数" aria-label="Permalink to &quot;変数&quot;">​</a></h4><ul><li><code>KSU</code> (bool): スクリプトが KernelSU 環境で実行されていることを示すための変数で、この変数の値は常に true になります。KernelSU と Magisk を区別するために使用できます。</li><li><code>KSU_VER</code> (string): 現在インストールされている KernelSU のバージョン文字列 (例: <code>v0.4.0</code>)</li><li><code>KSU_VER_CODE</code> (int): ユーザー空間に現在インストールされているKernelSUのバージョンコード (例: <code>10672</code>)</li><li><code>KSU_KERNEL_VER_CODE</code> (int): 現在インストールされている KernelSU のカーネル空間でのバージョンコード（例：<code>10672</code>）</li><li><code>BOOTMODE</code> (bool): KernelSU では常に <code>true</code></li><li><code>MODPATH</code> (path): モジュールファイルがインストールされるパス</li><li><code>TMPDIR</code> (path): ファイルを一時的に保存しておく場所</li><li><code>ZIPFILE</code> (path): あなたのモジュールのインストールZIP</li><li><code>ARCH</code> (string): デバイスの CPU アーキテクチャ。値は <code>arm</code>、<code>arm64</code>、<code>x86</code>、<code>x64</code> のいずれか</li><li><code>IS64BIT</code> (bool): <code>ARCH</code> が <code>arm64</code> または <code>x64</code> のときは <code>true</code></li><li><code>API</code> (int): 端末の API レベル・Android のバージョン（例：Android 6.0 なら<code>23</code>）</li><li><code>KSU_UAPI_VER</code> (int): KernelSU ユーザー空間 (ksud) の UAPI バージョン（例：<code>2</code>）。カーネルドライバーに破壊的変更がある場合にこのバージョンが更新されます。モジュールはこの値で互換性を確認できます。</li><li><code>KSU_RUNTIME_MODE</code> (string): KernelSU の現在の実行モード。値は <code>built-in</code>（GKI モード、カーネルに組み込み）、<code>lkm</code>（起動時にカーネルモジュールとして読み込み）、または <code>late-load</code>（起動後にカーネルモジュールとして読み込み）のいずれかです。</li><li><code>KSU_LATE_LOAD</code> (int?): KernelSU が起動後に遅延読み込みされた場合、この変数の値は <code>1</code> になります。それ以外の場合、この変数は設定されません。</li></ul><div class="warning custom-block"><p class="custom-block-title">警告</p><p>KernelSU では、MAGISK_VER_CODE は常に25200、MAGISK_VER は常にv25.2です。この2つの変数で KernelSU 上で動作しているかどうかを判断するのはやめてください。</p></div><h4 id="機能" tabindex="-1">機能 <a class="header-anchor" href="#機能" aria-label="Permalink to &quot;機能&quot;">​</a></h4><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ui_print &lt;msg&gt;</span></span>
<span class="line"><span>    コンソールに &lt;msg&gt; を表示します</span></span>
<span class="line"><span>    カスタムリカバリーのコンソールでは表示されないため、「echo」の使用は避けてください</span></span>
<span class="line"><span></span></span>
<span class="line"><span>abort &lt;msg&gt;</span></span>
<span class="line"><span>    エラーメッセージ&lt;msg&gt;をコンソールに出力し、インストールを終了させます</span></span>
<span class="line"><span>    終了時のクリーンアップがスキップされてしまうため、「exit」の使用は避けてください</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm &lt;target&gt; &lt;owner&gt; &lt;group&gt; &lt;permission&gt; [context]</span></span>
<span class="line"><span>    [context] が設定されていない場合、デフォルトは &quot;u:object_r:system_file:s0&quot; です。</span></span>
<span class="line"><span>    この機能は、次のコマンドの略記です：</span></span>
<span class="line"><span>       chown owner.group target</span></span>
<span class="line"><span>       chmod permission target</span></span>
<span class="line"><span>       chcon context target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm_recursive &lt;directory&gt; &lt;owner&gt; &lt;group&gt; &lt;dirpermission&gt; &lt;filepermission&gt; [context]</span></span>
<span class="line"><span>    [context] が設定されていない場合、デフォルトは &quot;u:object_r:system_file:s0&quot; です。</span></span>
<span class="line"><span>    &lt;directory&gt; 内のすべてのファイルに対しては以下が実行されます:</span></span>
<span class="line"><span>       set_perm file owner group filepermission context</span></span>
<span class="line"><span>    &lt;directory&gt; 内のすべてのディレクトリ（自身を含む）に対しては以下が実行されます:</span></span>
<span class="line"><span>       set_perm dir owner group dirpermission context</span></span></code></pre></div><h2 id="ブートスクリプト" tabindex="-1">ブートスクリプト <a class="header-anchor" href="#ブートスクリプト" aria-label="Permalink to &quot;ブートスクリプト&quot;">​</a></h2><p>KernelSU では、スクリプトは実行モードによって post-fs-data モードと late_start サービスモードの2種類に分けられます：</p><ul><li>post-fs-data モード <ul><li>同期処理です。実行が終わるか、10秒が経過するまでブートプロセスが一時停止されます。</li><li>スクリプトはモジュールがマウントされる前に実行されます。モジュール開発者はモジュールがマウントされる前に、動的にモジュールを調整できます。</li><li>このステージは Zygote が始まる前に起こるので、Android のほぼすべての処理の前に割り込めます</li><li><strong>警告:</strong> <code>setprop</code> を使うとブートプロセスのデッドロックを引き起こします! <code>resetprop -n &lt;prop_name&gt; &lt;prop_value&gt;</code> を使ってください。</li><li><strong>本当に必要な場合だけこのモードでコマンド実行してください</strong></li></ul></li><li>late_start サービスモード <ul><li>非同期処理です。スクリプトは、起動プロセスの残りの部分と並行して実行されます。</li><li><strong>ほとんどのスクリプトにはこちらがおすすめです</strong></li></ul></li></ul><p>KernelSU では、起動スクリプトは保存場所によって一般スクリプトとモジュールスクリプトの2種類に分けられます：</p><ul><li>一般スクリプト <ul><li><code>/data/adb/post-fs-data.d</code> か <code>/data/adb/service.d</code> に配置されます</li><li>スクリプトが実行可能な状態に設定されている場合にのみ実行されます (<code>chmod +x script.sh</code>)</li><li><code>post-fs-data.d</code> のスクリプトは post-fs-data モードで実行され、<code>service.d</code> のスクリプトは late_start サービスモードで実行されます</li><li>モジュールはインストール時に一般スクリプトを追加するべきではありません</li></ul></li><li>モジュールスクリプト <ul><li>モジュール独自のフォルダに配置されます</li><li>モジュールが有効な場合のみ実行されます</li><li><code>post-fs-data.sh</code> は post-fs-data モードで実行され、<code>service.sh</code> は late_start サービスモードで実行されます</li></ul></li></ul><p>すべてのブートスクリプトは、KernelSU の Busybox <code>ash</code> シェルで「スタンドアロンモード」を有効にした状態で実行されます。</p><h2 id="late-load-mode" tabindex="-1">Late-load モード <a class="header-anchor" href="#late-load-mode" aria-label="Permalink to &quot;Late-load モード {#late-load-mode}&quot;">​</a></h2><p>上記の標準起動フローに加えて、KernelSU は LKM（ローダブルカーネルモジュール）シナリオ向けの <strong>late-load モード</strong> をサポートしています。このモードでは、KernelSU カーネルモジュールは init プロセス中ではなく、<strong>システムが完全に起動した後</strong> にロードされます。</p><h3 id="late-load-はいつ発生するか" tabindex="-1">late-load はいつ発生するか？ <a class="header-anchor" href="#late-load-はいつ発生するか" aria-label="Permalink to &quot;late-load はいつ発生するか？&quot;">​</a></h3><p><code>ksud late-load</code> コマンドを実行することでトリガーされます。このコマンドは：</p><ol><li>現在の KMI バージョンを検出し、組み込みアセットから対応する <code>kernelsu.ko</code> をロードします。</li><li>通常起動時に行われるモジュールの初期化（SELinux ルール、許可リスト、機能など）を実行します。</li></ol><p>システムが既に完全に稼働しているため、起動時の特定のメカニズムは利用不可または不要です。</p><h3 id="標準起動との違い" tabindex="-1">標準起動との違い <a class="header-anchor" href="#標準起動との違い" aria-label="Permalink to &quot;標準起動との違い&quot;">​</a></h3><table tabindex="0"><thead><tr><th>動作</th><th style="text-align:center;">標準起動</th><th style="text-align:center;">Late-load モード</th></tr></thead><tbody><tr><td>カーネルモジュールが init (PID 1) によりロード</td><td style="text-align:center;">はい</td><td style="text-align:center;">いいえ（起動後にロード）</td></tr><tr><td>initrc 挿入 (モジュールの <code>.rc</code> ファイルを init.rc に挿入)</td><td style="text-align:center;">はい</td><td style="text-align:center;">利用不可</td></tr><tr><td>ksud の kprobe フック (execve/read/fstat/input)</td><td style="text-align:center;">はい</td><td style="text-align:center;">スキップ</td></tr><tr><td>セーフモード検出（音量キー）</td><td style="text-align:center;">はい</td><td style="text-align:center;">常に無効</td></tr><tr><td>起動ログのキャプチャ (logcat/dmesg)</td><td style="text-align:center;">はい</td><td style="text-align:center;">スキップ</td></tr><tr><td>Magisk 共存チェック</td><td style="text-align:center;">はい</td><td style="text-align:center;">スキップ</td></tr><tr><td><code>post-fs-data</code> イベントのカーネル通知</td><td style="text-align:center;">はい</td><td style="text-align:center;">スキップ</td></tr><tr><td><code>boot-completed</code> イベントのカーネル通知</td><td style="text-align:center;">はい</td><td style="text-align:center;">初期化時に直接設定</td></tr><tr><td><code>post-fs-data.sh</code> / <code>post-fs-data.d/</code> スクリプト</td><td style="text-align:center;">はい</td><td style="text-align:center;"><code>late-load</code> ステージで代替</td></tr><tr><td><code>system.prop</code> の読み込み</td><td style="text-align:center;">はい</td><td style="text-align:center;">はい</td></tr><tr><td>OverlayFS マウント（metamodule）</td><td style="text-align:center;">はい</td><td style="text-align:center;">はい</td></tr><tr><td><code>post-mount.sh</code> / <code>post-mount.d/</code> スクリプト</td><td style="text-align:center;">はい</td><td style="text-align:center;">はい</td></tr><tr><td><code>service.sh</code> / <code>service.d/</code> スクリプト</td><td style="text-align:center;">はい</td><td style="text-align:center;">はい</td></tr><tr><td><code>boot-completed.sh</code> / <code>boot-completed.d/</code> スクリプト</td><td style="text-align:center;">はい</td><td style="text-align:center;">はい</td></tr><tr><td>環境変数 <code>KSU_LATE_LOAD</code></td><td style="text-align:center;">未設定</td><td style="text-align:center;"><code>1</code> に設定</td></tr><tr><td>カーネル info フラグ <code>0x4</code></td><td style="text-align:center;">未設定</td><td style="text-align:center;">設定済み</td></tr></tbody></table><h3 id="スクリプト実行順序" tabindex="-1">スクリプト実行順序 <a class="header-anchor" href="#スクリプト実行順序" aria-label="Permalink to &quot;スクリプト実行順序&quot;">​</a></h3><p>late-load モードでのスクリプト実行順序は以下の通りです：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ksud late-load:</span></span>
<span class="line"><span>  1. kernelsu.ko をロード（まだロードされていない場合）</span></span>
<span class="line"><span>  2. バイナリの展開、モジュール更新の処理、SELinux ルールの読み込み、機能の初期化</span></span>
<span class="line"><span>  3. late-load.d/ の汎用スクリプトとモジュールの late-load スクリプトを実行（ブロッキング）</span></span>
<span class="line"><span>  4. system.prop を読み込み (resetprop -n)</span></span>
<span class="line"><span>  5. metamodule マウントスクリプトを実行（OverlayFS マウント）</span></span>
<span class="line"><span>  6. post-mount.d/ の汎用スクリプトとモジュールの post-mount.sh を実行（ブロッキング）</span></span>
<span class="line"><span>  7. service.d/ の汎用スクリプトとモジュールの service.sh を実行（ノンブロッキング）</span></span>
<span class="line"><span>  8. boot-completed.d/ の汎用スクリプトとモジュールの boot-completed.sh を実行（ノンブロッキング）</span></span></code></pre></div><h3 id="late-load-専用スクリプト" tabindex="-1">Late-load 専用スクリプト <a class="header-anchor" href="#late-load-専用スクリプト" aria-label="Permalink to &quot;Late-load 専用スクリプト&quot;">​</a></h3><p>モジュールは <code>late-load.sh</code> スクリプトを提供でき、このスクリプトは <strong>late-load モードでのみ</strong> 実行され、<code>post-fs-data.sh</code> の代替として機能します。このスクリプトは OverlayFS マウント前に実行され、標準フローの <code>post-fs-data.sh</code> と同様のタイミングです。</p><p>また、汎用スクリプトを <code>/data/adb/late-load.d/</code> に配置して、このステージで実行することもできます。</p><h3 id="スクリプト内で-late-load-モードを検出する" tabindex="-1">スクリプト内で late-load モードを検出する <a class="header-anchor" href="#スクリプト内で-late-load-モードを検出する" aria-label="Permalink to &quot;スクリプト内で late-load モードを検出する&quot;">​</a></h3><p>モジュールは環境変数 <code>KSU_LATE_LOAD</code> をチェックすることで late-load モードかどうかを検出できます：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$KSU_LATE_LOAD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # late-load モードで実行中</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Late-load mode detected&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><p>これにより、モジュールは自身の動作を調整できます。例えば、早期起動時にのみ必要な操作をスキップできます。</p>`,105)])])}const g=e(l,[["render",o]]);export{u as __pageData,g as default};
